changeSet.sql:
-- Xavfsizlik: buyer_in/seller_in null bo'lgan eski yozuvlarni UUID'dan backfill (drop'dan oldin).
UPDATE document.contracts c
   SET buyer_in = (SELECT COALESCE(u.pinfl, u.tin) FROM "user"."user" u WHERE u.id = c.buyer_user_id)
 WHERE c.buyer_in IS NULL AND c.buyer_user_id IS NOT NULL;
UPDATE document.contracts c
   SET seller_in = (SELECT COALESCE(u.pinfl, u.tin) FROM "user"."user" u WHERE u.id = c.seller_user_id)
 WHERE c.seller_in IS NULL AND c.seller_user_id IS NOT NULL;

ALTER TABLE document.contracts DROP COLUMN IF EXISTS buyer_user_id;
ALTER TABLE document.contracts DROP COLUMN IF EXISTS seller_user_id;
